// Tafsirs that are ours rather than the Quran Foundation's list (ids are strings "<lang>.<name>", never numbers):
//  - ml.thafheem   Thafheemul Quran (Malayalam), lib/thafheem.ts, text from R2;
//  - SPA5K_EDITIONS (owntafsir-editions.ts, generated by pipeline/spa5k_tafsirs.py from the editions that passed its
//    quality gate): our own copy of spa5k/tafsir_api in R2, tafsir/<id>/v1/<surah>.json =
//    {surah, ayahs: [{ayah, text, to?}]}, an entry with `to` = one text for the ayahs ayah..to (the same long passage was
//    repeated for each ayah of a group); an ayah without an entry has no text. Plain text, paragraphs at line breaks;
//  - ml.amani      Amani Thafseer (Malayalam, Muhammad Amani Moulavi; amanithafseer.com, pipeline/ml_amani.py; owner,
//    12 Oct 2026), in the same storage format: one entry per block of ayahs, the block's translations ("(153) …") then
//    its commentary;
//  - QF_NOTES: tafsirs that the Quran Foundation has as a translation with footnotes (the commentary), served live: the
//    ayah's translation with numbered markers, its footnotes from /foot_notes/<id>. en.tafheem = Tafhim al-Qur'an
//    (Maududi, English, translation 95); ur.tafheem = Tafheem ul Quran (Urdu, 97); ur.usmani = Tafsir-e-Usmani (Urdu: Shaykh
//    al-Hind's translation with Shabbir Ahmad Usmani's notes, 151) (owner, 12 Oct 2026).
import type { TafsirInfo, TafsirResponse } from "../../../../contracts/types";
import { SPA5K_EDITIONS } from "./owntafsir-editions";
import { QfError, qfGet } from "./qf";
import { formatTafsir } from "./tafsir";
import { THAFHEEM } from "./thafheem";

export const TAFHEEM_EN_ID = "en.tafheem";
/** Ours, but read from the Quran Foundation (a translation's footnotes): offered only when its credentials are set. */
const QF_NOTES: { info: TafsirInfo; translation: number }[] = [
  { info: { id: TAFHEEM_EN_ID, name: "Tafhim al-Qur'an", author: "Sayyid Abul A'la Maududi", lang: "en" }, translation: 95 },
  { info: { id: "ur.tafheem", name: "Tafheem ul Quran", author: "Sayyid Abul A'la Maududi", lang: "ur" }, translation: 97 },
  { info: { id: "ur.usmani", name: "Tafsir-e-Usmani", author: "Shabbir Ahmad Usmani", lang: "ur" }, translation: 151 },
];
export const TAFHEEM_EN = QF_NOTES[0].info;
export const needsQf = (id: string | number) => QF_NOTES.some((x) => x.info.id === id);

export const AMANI: TafsirInfo = { id: "ml.amani", name: "അമാനി തഫ്സീർ", author: "Muhammad Amani Moulavi", lang: "ml" };

/** Every tafsir of ours the Worker can serve now (those that come from the Quran Foundation only with its credentials). */
export const ownTafsirs = (qf: boolean): TafsirInfo[] => [THAFHEEM, AMANI, ...SPA5K_EDITIONS, ...(qf ? QF_NOTES.map((x) => x.info) : [])];

const escape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

interface SurahFile { ayahs?: { ayah: number; text: string; to?: number }[] }
type Passage = Pick<TafsirResponse, "from" | "to" | "html">;

/** The text for one ayah of an edition from our storage: the passage that covers it, in paragraphs (empty html when the
 *  edition has nothing for the ayah). */
export async function ownText(media: R2Bucket, id: string, lang: string, [surah, ayah]: [number, number]): Promise<Passage> {
  const object = await media.get(`tafsir/${id}/v1/${surah}.json`);
  if (!object) throw new QfError(404, "no tafsir");
  const entry = ((await object.json<SurahFile>()).ayahs ?? []).find((a) => a.ayah <= ayah && ayah <= (a.to ?? a.ayah));
  const paragraphs = String(entry?.text ?? "").split(/\r?\n/).map((p) => p.trim()).filter(Boolean).map((p) => `<p>${escape(p)}</p>`);
  const [from, to] = entry ? [entry.ayah, Math.max(entry.ayah, entry.to ?? entry.ayah)] : [ayah, ayah];
  return { from: `${surah}:${from}`, to: `${surah}:${to}`, html: formatTafsir(paragraphs.join(""), lang) };
}

interface QfTranslation { translations?: { text?: string }[] }
interface QfFootNote { foot_note?: { text?: string } }
/** More footnotes than any ayah has (2:255 has about 20); a cap on requests to the source. */
const MAX_NOTES = 40;

/** A QF_NOTES tafsir (Tafhim al-Qur'an and the like) for one ayah: its translation as a "rf-tr" paragraph with the note numbers in superscript, then each
 *  note as "<strong>1.</strong> text" (the pattern Thafheem uses). The source's markers are <sup foot_note="id">1</sup>;
 *  the sanitiser keeps sup and drops the attribute. An ayah without notes is just the translation line. A note that cannot
 *  be fetched fails the whole answer (not cached), so no passage is stored with notes missing. */
export async function qfNotes(env: Parameters<typeof qfGet>[0], id: string | number, [surah, ayah]: [number, number]): Promise<Passage> {
  const source = QF_NOTES.find((x) => x.info.id === id);
  if (!source) throw new QfError(404, "no tafsir");
  const ref = `${surah}:${ayah}`;
  const d = await qfGet<QfTranslation>(env, `/content/api/v4/quran/translations/${source.translation}?verse_key=${ref}`);
  const text = String(d.translations?.[0]?.text ?? "");
  const marks = [...text.matchAll(/<sup\b[^>]*\bfoot_note="?(\d+)"?[^>]*>\s*(\d+)\s*<\/sup>/g /* quoted or not: Tafsir-e-Usmani's are bare */)].slice(0, MAX_NOTES);
  const notes = await Promise.all(marks.map(async (m) => ({ n: +m[2], text: String((await qfGet<QfFootNote>(env, `/content/api/v4/foot_notes/${m[1]}`)).foot_note?.text ?? "") })));
  const html = [`<p class="text-translation">${text}</p>`, ...notes.filter((n) => n.text.trim()).map((n) => `<p><strong>${n.n}.</strong> ${n.text}</p>`)].join("");
  return { from: ref, to: ref, html: formatTafsir(html, source.info.lang) };
}

